from nanobrain.core.step import BaseStep, StepConfig

class ConcatStepConfig(StepConfig):
    model_config = ConfigDict(extra="forbid", validate_assignment=False)
    sep: str | None = Field(default=None)

class ConcatStep(BaseStep):
    COMPONENT_TYPE = "concat_step"

    @classmethod
    def _get_config_class(cls):
        return ConcatStepConfig

    async def process(self, input_data: dict, **kwargs) -> dict:
        parts = input_data["parts"]
        sep = kwargs.get("sep", self._config.sep)
        joined = sep.join(parts)
        return {"joined": joined}

