class DedupePreserveOrderStep(BaseStep):
    COMPONENT_TYPE = "dedupe_preserve_order"

    @classmethod
    def _get_config_class(cls):
        return DedupePreserveOrderStepConfig

    async def process(self, input_data: dict, **kwargs) -> dict:
        seen = set()
        unique_items = []
        for item in input_data["items"]:
            if item not in seen:
                seen.add(item)
